"""Native original macro/type excerpts versus linked CON variable operations."""
import hashlib,json,re,subprocess,tempfile
from pathlib import Path
from verify_original_demo_snapshot_heap import ROOT,run_browser_probe
if __name__=='__main__':
 profile=json.loads((ROOT/'tools/browser_classic_profile.json').read_text());source=ROOT/profile['prepared_source_root']
 header=(source/'source/duke3d/src/gamevars.h').read_text();gamedef=(source/'source/duke3d/src/gamedef.h').read_text()
 enum=re.search(r'enum GamevarFlags_t\s*\{.*?\};',header,re.S)[0]
 end=header.index('} gamevar_t;')+len('} gamevar_t;');record=header[header.rfind('typedef struct',0,end):end]
 end=gamedef.index('} vmstate_t;')+len('} vmstate_t;');vmtype=gamedef[gamedef.rfind('typedef struct',0,end):end]
 macro=header[header.index('#define VM_GAMEVAR_OPERATOR('):header.index('static FORCE_INLINE void __fastcall Gv_DivVar')]
 calls=header[header.index('VM_GAMEVAR_OPERATOR(Gv_AddVar'):header.index('#undef VM_GAMEVAR_OPERATOR')]
 names=['Gv_AddVar','Gv_SubVar','Gv_MulVar','Gv_ModVar','Gv_AndVar','Gv_XorVar','Gv_OrVar','Gv_ShiftVarL','Gv_ShiftVarR']
 flags=[0,1,2,0x2000,0x8000,0x100000,0x140000]
 unit='#include <cstdio>\n#include "fix16.hpp"\n#define MAXPLAYERS 16\n#define MAXSPRITES 16384\n#define MAXGAMEVARS 2048\nstruct spritetype;struct uspritetype;struct DukePlayer_t;struct actor_t;\n'+enum+'\n#pragma pack(push,1)\n'+record+'\n#pragma pack(pop)\n'+vmtype+'\ngamevar_t aGameVars[MAXGAMEVARS];vmstate_t vm;\n'+macro+calls+'\n'
 unit+='int main(){printf("%zu,%zu\\n",sizeof(gamevar_t),sizeof(vmstate_t));void(*ops[])(int,int32_t)={'+','.join(names)+'};int flags[]={'+','.join(map(str,flags))+'};intptr_t values[MAXSPRITES]={};vm.playerNum=-1;vm.spriteNum=-2;'
 unit+='for(int op=0;op<9;op++)for(int mode=0;mode<7;mode++)for(int n=1;n<=24;n++){int operand=(op>=7?n%4:2+n%5);int32_t v32=n,vq=n*65536+32768;int16_t v16=n;values[0]=12345;values[15]=n;values[16382]=n;aGameVars[0]={};aGameVars[0].defaultValue=321;aGameVars[0].flags=flags[mode];'
 unit+='switch(mode){case 0:aGameVars[0].global=n;break;case 1:case 2:aGameVars[0].pValues=values;break;case 3:aGameVars[0].pValues=(intptr_t*)&v32;break;case 4:aGameVars[0].pValues=(intptr_t*)&v16;break;default:aGameVars[0].pValues=(intptr_t*)&vq;break;}intptr_t before=aGameVars[0].global;ops[op](0,operand);intptr_t result=mode==0?aGameVars[0].global:mode==1?values[15]:mode==2?values[16382]:mode==3?v32:mode==4?v16:vq;printf("%lld,%lld,%d,%d\\n",(long long)result,(long long)values[0],(int)(aGameVars[0].flags==flags[mode]&&aGameVars[0].defaultValue==321),(int)(mode==0||aGameVars[0].global==before));}}\n'
 with tempfile.TemporaryDirectory(prefix='original-con-operators-') as folder:
  folder=Path(folder);cpp=folder/'oracle.cpp';exe=folder/'oracle.exe';cpp.write_text(unit)
  build=subprocess.run(['clang++','-std=c++14','-funsigned-char','-DNOASM','-I'+str(source/'source/build/include'),str(cpp),str(source/'source/build/src/fix16.cpp'),'-o',str(exe)],capture_output=True,text=True);assert build.returncode==0,build.stderr
  rows=subprocess.check_output([str(exe)],text=True).splitlines();sizes=[int(v) for v in rows[0].split(',')];expected=[[int(v) for v in row.split(',')] for row in rows[1:]]
 probe=r"""async base=>{const {NativeRuntime}=await import('/runtime/index.mjs');const r=new NativeRuntime({renderer:'canvas2d',memoryBytes:16<<20});r.bindSourceMemory();const release=(await import(base+'/browser-abi/libc_provider.mjs')).bindBrowserC(r);const ptrs=[];try{const layer=await import(base+'/source/build/src/baselayer.cpp.mjs');layer.engineSetupAllocator();const game=await import(base+'/source/duke3d/src/gameexec.cpp.mjs'),vars=await import(base+'/source/duke3d/src/gamevars.cpp.mjs');const slot=vars.aGameVars[0],state=game.vm,space=globalThis[Symbol.for('source-lp64-addresses/2')],allocate=n=>{const p=r.heap.malloc(n,8);ptrs.push(p);return p;};const array=allocate(16384*8),i32=allocate(8),i16=allocate(8),q16=allocate(8);const view=()=>new DataView(r.heap.buffer),results=[];state.playerNum=-1;state.spriteNum=-2;for(let op=0;op<9;op++)for(let mode=0;mode<7;mode++)for(let n=1;n<=24;n++){const operand=op>=7?n%4:2+n%5;view().setBigInt64(array,12345n,true);view().setBigInt64(array+15*8,BigInt(n),true);view().setBigInt64(array+16382*8,BigInt(n),true);view().setInt32(i32,n,true);view().setInt16(i16,n,true);view().setInt32(q16,n*65536+32768,true);slot.defaultValue=321n;slot.flags=BigInt(FLAGS[mode]);slot.__cxx_anonymous_0.global=mode===0?BigInt(n):BigInt(mode<=2?array:mode===3?i32:mode===4?i16:q16);const before=slot.__cxx_anonymous_0.global;game[NAMES[op]](0,operand);const result=mode===0?Number(slot.__cxx_anonymous_0.global):mode<=2?Number(view().getBigInt64(array+(mode===1?15:16382)*8,true)):mode===3?view().getInt32(i32,true):mode===4?view().getInt16(i16,true):view().getInt32(q16,true);results.push([result,Number(view().getBigInt64(array,true)),Number(slot.flags===BigInt(FLAGS[mode])&&slot.defaultValue===321n),Number(mode===0||slot.__cxx_anonymous_0.global===before)]);}const marker=Symbol.for('source-first.original-byte-record-storage/1');return {results,gamevar_bytes:slot[marker]?.bytes?.length??null,vm_bytes:state[marker]?.bytes?.length??null,gameplay_verified:false};}finally{for(const p of ptrs)r.heap.free(p);release();r.close();}}""".replace('FLAGS',json.dumps(flags)).replace('NAMES',json.dumps(names))
 actual=run_browser_probe(probe)
 assert sizes==[32,48],sizes
 for key,expected_size in zip(('gamevar_bytes','vm_bytes'),sizes):
  if actual[key] is not None:assert actual[key]==expected_size,(key,actual[key],expected_size)
 assert actual['results']==expected,next(((i,a,b) for i,(a,b) in enumerate(zip(actual['results'],expected)) if a!=b),None)
 report={'original_con_variable_operators_verified':True,'original_functions':names,'native_chromium_operations':len(expected),'native_chromium_values':len(expected)*4,'storage_modes':['global','per-player','per-actor','int32-pointer','int16-pointer','q16-pointer','raw-q16-pointer'],'original_gamevar_bytes':sizes[0],'original_vm_bytes':sizes[1],'browser_gamevar_byte_storage_bytes':actual['gamevar_bytes'],'browser_vm_byte_storage_bytes':actual['vm_bytes'],'scope':'original operator/type excerpts; complete VM byte-storage parity is not claimed','original_macro_sha256':hashlib.sha256((macro+calls).encode()).hexdigest(),'native_source_sha256':hashlib.sha256(unit.encode()).hexdigest(),'results_sha256':hashlib.sha256(json.dumps(expected).encode()).hexdigest(),'gameplay_verified':False}
 (ROOT/'reports/nov19-original-con-variable-operators.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS',len(expected),'original CON mutations across seven native storage modes in Chromium')
